// components/ScriptReader.js - Improved Version

import React, { useState, useCallback } from 'react';
import { FileText, UploadCloud, Eye, EyeOff, Download, Trash2 } from 'lucide-react';
import * as mammoth from "mammoth";

const ScriptReader = () => {
  const [scriptContent, setScriptContent] = useState('');
  const [scriptText, setScriptText] = useState('');
  const [fileName, setFileName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showRawText, setShowRawText] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Helper functions for better detection (moved outside to fix useCallback dependencies)
  const isCharacterName = (text, lines = [], index = 0) => {
    // Common character names from your script
    const knownCharacters = ['JAX', 'JETT', 'GIRL', 'YOUNG JAX', 'Jax', 'Jett', 'Girl', 'Young Jax'];
    
    if (knownCharacters.includes(text)) return true;
    
    // General character name patterns
    if (text.length > 25) return false; // Too long to be a character name
    if (/[.!?,:;]/.test(text)) return false; // Contains punctuation
    
    // Check if it's all caps and short
    if (/^[A-Z\s]+$/.test(text) && text.length >= 2 && text.length <= 20) {
      return true;
    }
    
    // Check if it's title case and looks like a name
    if (/^[A-Z][a-z]+(\s[A-Z][a-z]+)*$/.test(text) && text.length <= 20) {
      return true;
    }
    
    return false;
  };

  const isSceneHeading = (text) => {
    return /^(INT\.|EXT\.|FADE IN|FADE OUT|CUT TO)/.test(text.toUpperCase());
  };

  const isTransition = (text) => {
    const transitions = ['FADE IN', 'FADE OUT', 'CUT TO', 'DISSOLVE TO', 'SMASH CUT', 'CRASH'];
    return transitions.some(t => text.toUpperCase().includes(t));
  };

  const isTitleLine = (text) => {
    // Title, author, copyright, etc.
    return (
      text.includes('Melodic Justice') ||
      text.includes('By ') ||
      /^\([^)]*\d{1,2}\/\d{1,2}\/\d{2,4}[^)]*\)/.test(text) ||
      text.includes('©') ||
      (text.length < 50 && /^[A-Z\s]+$/.test(text) && !isCharacterName(text))
    );
  };

  const isActionLine = (text, lines = [], index = 0) => {
    // Action lines are typically longer and descriptive
    if (text.length < 10) return false;
    
    // Contains descriptive words
    const actionWords = ['sees', 'walks', 'sits', 'stands', 'looks', 'hears', 'feels', 'moves', 'turns'];
    const hasActionWords = actionWords.some(word => text.toLowerCase().includes(word));
    
    // Is in italics (from original formatting)
    const isItalic = text.includes('<em>') || text.includes('<i>');
    
    return hasActionWords || isItalic || text.length > 80;
  };

  // Better processing for plain text scripts
  const processPlainTextScript = (text) => {
    const lines = text.split('\n');
    let processedLines = [];
    
    lines.forEach((line, index) => {
      const trimmed = line.trim();
      
      if (!trimmed) {
        processedLines.push('<br>');
        return;
      }

      // Check if line is centered by looking at surrounding whitespace
      const leadingSpaces = line.length - line.trimLeft().length;
      const totalLength = line.length;
      const isCentered = leadingSpaces > 10 && (totalLength - leadingSpaces - trimmed.length) > 5;
      
      // Character names - typically standalone, short, and may be centered
      if (isCharacterName(trimmed, lines, index)) {
        processedLines.push(`<p class="character">${trimmed}</p>`);
      }
      // Scene headings - usually all caps and specific format
      else if (isSceneHeading(trimmed)) {
        processedLines.push(`<p class="scene-heading">${trimmed}</p>`);
      }
      // Transitions - typically right-aligned or centered
      else if (isTransition(trimmed)) {
        processedLines.push(`<p class="transition">${trimmed}</p>`);
      }
      // Centered text (titles, etc.)
      else if (isCentered || isTitleLine(trimmed)) {
        processedLines.push(`<p class="center">${trimmed}</p>`);
      }
      // Action lines - longer descriptive text
      else if (isActionLine(trimmed, lines, index)) {
        processedLines.push(`<p class="action">${trimmed}</p>`);
      }
      // Default to dialogue or regular text
      else {
        processedLines.push(`<p class="dialogue">${trimmed}</p>`);
      }
    });
    
    return processedLines.join('\n');
  };

  // Improved HTML processing for Word docs
  const improvedHtmlProcessing = (html) => {
    // Remove mammoth's default paragraph styling that might interfere
    let processed = html.replace(/<p[^>]*>/g, '<p>');
    
    // Split into lines for analysis
    const paragraphs = processed.split('</p>').filter(p => p.trim());
    
    let result = [];
    
    paragraphs.forEach(paragraph => {
      let content = paragraph.replace('<p>', '').trim();
      if (!content) return;
      
      // Remove any remaining HTML tags for analysis
      const textContent = content.replace(/<[^>]*>/g, '').trim();
      
      if (isCharacterName(textContent)) {
        result.push(`<p class="character">${content}</p>`);
      } else if (isSceneHeading(textContent)) {
        result.push(`<p class="scene-heading">${content}</p>`);
      } else if (isTransition(textContent)) {
        result.push(`<p class="transition">${content}</p>`);
      } else if (isTitleLine(textContent)) {
        result.push(`<p class="center">${content}</p>`);
      } else if (isActionLine(textContent)) {
        result.push(`<p class="action">${content}</p>`);
      } else {
        result.push(`<p class="dialogue">${content}</p>`);
      }
    });
    
    return result.join('\n');
  };

  const saveToStorage = (html, text, filename) => {
    localStorage.setItem('melodicJustice_script_html', html);
    localStorage.setItem('melodicJustice_script_text', text);
    localStorage.setItem('melodicJustice_script_filename', filename);
  };

  const handleFileUpload = useCallback(async (event) => {
    const file = event.target.files[0];

    if (file) {
      setIsLoading(true);
      setFileName(file.name);
      
      try {
        if (file.type === 'text/plain') {
          const reader = new FileReader();
          reader.onload = (e) => {
            const text = e.target.result;
            const htmlContent = processPlainTextScript(text);
            setScriptContent(htmlContent);
            setScriptText(text);
            saveToStorage(htmlContent, text, file.name);
          };
          reader.readAsText(file);
        } else if (
          file.type === 'application/msword' || 
          file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
        ) {
          const arrayBuffer = await file.arrayBuffer();
          
          // Use mammoth with custom style mapping to preserve formatting better
          const options = {
            styleMap: [
              "p[style-name='Character'] => p.character",
              "p[style-name='Scene Heading'] => p.scene-heading", 
              "p[style-name='Action'] => p.action",
              "p[style-name='Dialogue'] => p.dialogue",
              "p[style-name='Parenthetical'] => p.parenthetical",
              "p[style-name='Transition'] => p.transition"
            ]
          };
          
          const htmlResult = await mammoth.convertToHtml({ 
            arrayBuffer: arrayBuffer,
            ...options
          });
          
          const textResult = await mammoth.extractRawText({ arrayBuffer: arrayBuffer });
          
          // Process the HTML with better logic
          let processedHtml = improvedHtmlProcessing(htmlResult.value);
          
          setScriptContent(processedHtml);
          setScriptText(textResult.value);
          saveToStorage(processedHtml, textResult.value, file.name);

          if (htmlResult.messages.length > 0) {
            console.log('Conversion messages:', htmlResult.messages);
          }
        } else {
          alert('Please upload a plain text (.txt), .doc, or .docx file.');
        }
      } catch (error) {
        console.error("Error processing file:", error);
        alert(`Error reading file: ${error.message}`);
      } finally {
        setIsLoading(false);
      }
    }
  }, []);



  // Load saved script on component mount
  React.useEffect(() => {
    const savedScriptHtml = localStorage.getItem('melodicJustice_script_html');
    const savedScriptText = localStorage.getItem('melodicJustice_script_text');
    const savedFileName = localStorage.getItem('melodicJustice_script_filename');
    
    if (savedScriptHtml && savedScriptText) {
      setScriptContent(savedScriptHtml);
      setScriptText(savedScriptText);
      setFileName(savedFileName || 'Saved Script');
    }
  }, []);

  // Clear script
  const clearScript = () => {
    if (window.confirm('Are you sure you want to clear the current script?')) {
      setScriptContent('');
      setScriptText('');
      setFileName('');
      setSearchTerm('');
      localStorage.removeItem('melodicJustice_script_html');
      localStorage.removeItem('melodicJustice_script_text');
      localStorage.removeItem('melodicJustice_script_filename');
    }
  };

  // Download script as HTML
  const downloadScript = () => {
    if (!scriptContent) return;
    
    const htmlContent = `
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>${fileName || 'Script'}</title>
    <style>
        body { 
            font-family: 'Courier New', monospace; 
            line-height: 1.6; 
            max-width: 800px; 
            margin: 0 auto; 
            padding: 40px 20px;
            background: white;
            color: black;
        }
        .character { 
            font-weight: bold; 
            text-align: center; 
            margin: 20px 0 10px 0; 
            text-transform: uppercase;
            font-size: 1em;
        }
        .scene-heading { 
            font-weight: bold; 
            text-transform: uppercase; 
            margin: 20px 0;
            text-decoration: underline;
        }
        .action { 
            margin: 10px 0; 
            font-style: italic;
            text-align: left;
        }
        .dialogue { 
            margin: 5px 60px; 
            text-align: left;
        }
        .parenthetical { 
            margin: 0 80px; 
            font-style: italic; 
            text-align: center;
        }
        .transition { 
            text-align: right; 
            font-weight: bold; 
            margin: 20px 0; 
            text-transform: uppercase;
        }
        .center { 
            text-align: center; 
            margin: 15px 0;
            font-weight: bold;
        }
        p { margin: 5px 0; }
    </style>
</head>
<body>
    ${scriptContent}
</body>
</html>`;
    
    const blob = new Blob([htmlContent], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${fileName.replace(/\.[^/.]+$/, '')}_formatted.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  // Highlight search terms in content
  const highlightSearchTerm = (content, searchTerm) => {
    if (!searchTerm.trim()) return content;
    
    const regex = new RegExp(`(${searchTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    return content.replace(regex, '<mark style="background-color: yellow; color: black;">$1</mark>');
  };

  const displayContent = searchTerm ? 
    highlightSearchTerm(scriptContent, searchTerm) : 
    scriptContent;

  return (
    <div className="rounded-lg p-6 fade-in shadow-xl" style={{ backgroundColor: '#2f2a2f' }}>
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <FileText className="w-8 h-8 text-cyan-400" />
          <div>
            <h2 className="text-2xl font-bold text-white">Script Reader</h2>
            <p className="text-gray-400">Upload and view your script with formatting preserved</p>
          </div>
        </div>
        
        <div className="flex items-center gap-3 flex-wrap">
          {scriptContent && (
            <>
              <button
                onClick={() => setShowRawText(!showRawText)}
                className="px-3 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded-lg flex items-center gap-2 transition-all"
                title={showRawText ? "Show formatted view" : "Show raw text"}
              >
                {showRawText ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                {showRawText ? "Format" : "Raw"}
              </button>
              
              <button
                onClick={downloadScript}
                className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg flex items-center gap-2 transition-all"
                title="Download as HTML"
              >
                <Download className="w-4 h-4" />
                Download
              </button>
              
              <button
                onClick={clearScript}
                className="px-3 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg flex items-center gap-2 transition-all"
                title="Clear script"
              >
                <Trash2 className="w-4 h-4" />
                Clear
              </button>
            </>
          )}
          
          <label className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-cyan-500 to-teal-500 hover:from-cyan-600 hover:to-teal-600 text-white rounded-lg transition-all shadow-md hover:shadow-lg">
            <UploadCloud className="w-5 h-5" />
            {isLoading ? 'Processing...' : 'Upload Script'}
            <input
              type="file"
              accept=".txt,.doc,.docx"
              onChange={handleFileUpload}
              className="hidden"
              disabled={isLoading}
            />
          </label>
        </div>
      </div>

      {/* Search Bar */}
      {scriptContent && (
        <div className="mb-6">
          <div className="relative max-w-md">
            <input
              type="text"
              placeholder="Search in script..."
              className="w-full px-4 py-2 bg-gray-800 border border-gray-700 rounded-lg text-white focus:ring-2 focus:ring-cyan-500 focus:outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {searchTerm && (
              <button
                onClick={() => setSearchTerm('')}
                className="absolute right-2 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-white"
              >
                ×
              </button>
            )}
          </div>
        </div>
      )}

      {/* Script Content */}
      <div className="bg-white rounded-lg shadow-inner" style={{ minHeight: '70vh' }}>
        {isLoading ? (
          <div className="flex items-center justify-center h-64">
            <div className="text-gray-600">Processing file...</div>
          </div>
        ) : scriptContent ? (
          <div 
            className="p-8 overflow-y-auto custom-scrollbar"
            style={{ 
              maxHeight: '70vh',
              fontFamily: showRawText ? 'Monaco, "Courier New", monospace' : '"Courier New", monospace',
              fontSize: '14px',
              lineHeight: '1.8',
              color: 'black'
            }}
          >
            {showRawText ? (
              <pre className="whitespace-pre-wrap">{scriptText}</pre>
            ) : (
              <div 
                dangerouslySetInnerHTML={{ __html: displayContent }}
                className="script-content"
              />
            )}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center h-64 text-gray-500">
            <FileText className="w-16 h-16 mb-4 opacity-50" />
            <p className="text-lg mb-2">No script loaded</p>
            <p className="text-sm">Upload a .txt, .doc, or .docx file to begin</p>
          </div>
        )}
      </div>

      {/* File Info */}
      {fileName && (
        <div className="mt-4 flex items-center justify-between text-sm text-gray-400">
          <div>
            <span className="font-medium">File:</span> {fileName}
          </div>
          {scriptText && (
            <div>
              <span className="font-medium">Characters:</span> {scriptText.length.toLocaleString()}
              <span className="ml-4 font-medium">Words:</span> {scriptText.split(/\s+/).filter(word => word.length > 0).length.toLocaleString()}
            </div>
          )}
        </div>
      )}

      {/* Enhanced CSS for script formatting */}
      <style jsx>{`
        .script-content .character {
          font-weight: bold;
          text-align: center;
          margin: 25px 0 10px 0;
          text-transform: uppercase;
          font-size: 1em;
          letter-spacing: 0.5px;
        }
        .script-content .scene-heading {
          font-weight: bold;
          text-transform: uppercase;
          margin: 30px 0 15px 0;
          text-decoration: underline;
          font-size: 1em;
        }
        .script-content .action {
          margin: 12px 0;
          font-style: italic;
          text-align: left;
          line-height: 1.6;
        }
        .script-content .dialogue {
          margin: 8px 80px 8px 160px;
          text-align: left;
          line-height: 1.5;
        }
        .script-content .parenthetical {
          margin: 5px 120px;
          font-style: italic;
          text-align: center;
          font-size: 0.9em;
        }
        .script-content .transition {
          text-align: right;
          font-weight: bold;
          margin: 25px 0;
          text-transform: uppercase;
          font-size: 1em;
        }
        .script-content .center {
          text-align: center;
          margin: 20px 0;
          font-weight: bold;
          font-size: 1.1em;
        }
        .script-content p {
          margin: 8px 0;
        }
      `}</style>
    </div>
  );
};

export default ScriptReader;
